import axios from 'axios'
import { ElMessage } from 'element-plus'
import router from '@/router'

// 创建axios实例
const service = axios.create({
  baseURL: '/api',
  timeout: 15000
})

// 请求拦截器
service.interceptors.request.use(
  config => {
    // 判断是否为管理端接口
    const isAdminAPI = config.url?.startsWith('/admin') || config.url?.startsWith('/report/list') || config.url?.startsWith('/report/handle') || config.url?.startsWith('/report/delete')
    
    // 管理端接口使用 adminToken，普通接口使用 token
    const token = isAdminAPI ? localStorage.getItem('adminToken') : localStorage.getItem('token')
    
    if (token) {
      config.headers['Authorization'] = 'Bearer ' + token
    }
    // 确保 POST 请求使用 application/json
    if (config.method === 'post' && !config.headers['Content-Type']) {
      config.headers['Content-Type'] = 'application/json'
    }
    return config
  },
  error => {
    console.error('请求错误：', error)
    return Promise.reject(error)
  }
)

// 响应拦截器
service.interceptors.response.use(
  response => {
    const res = response.data

    // 如果返回的状态码不是200，则认为是错误
    if (res.code !== 200) {
      // 401错误在登录/注册页面不显示提示
      const currentPath = router.currentRoute.value.path
      const isAuthPage = currentPath === '/login' || currentPath === '/register'
      
      if (res.code === 401) {
        localStorage.removeItem('token')
        localStorage.removeItem('userInfo')
        
        // 只有当前不在登录或注册页面时才显示提示和跳转
        if (!isAuthPage) {
          ElMessage({
            message: res.message || '未授权，请重新登录',
            type: 'error',
            duration: 3000
          })
          router.push('/login')
        }
      } else {
        // 非401错误正常显示提示
        ElMessage({
          message: res.message || '请求失败',
          type: 'error',
          duration: 3000
        })
      }

      return Promise.reject(new Error(res.message || '请求失败'))
    } else {
      return res
    }
  },
  error => {
    console.error('响应错误：', error)
    
    let message = '网络错误，请稍后重试'
    const currentPath = router.currentRoute.value.path
    const isAuthPage = currentPath === '/login' || currentPath === '/register'
    
    if (error.response) {
      switch (error.response.status) {
        case 400:
          message = error.response.data.message || '请求参数错误'
          break
        case 401:
          message = '未授权，请重新登录'
          localStorage.removeItem('token')
          localStorage.removeItem('userInfo')
          
          // 在登录/注册页面时,不显示提示也不跳转
          if (isAuthPage) {
            return Promise.reject(error)
          }
          
          // 只有当前不在登录或注册页面时才跳转
          router.push('/login')
          break
        case 403:
          message = '没有权限访问'
          break
        case 404:
          message = '请求资源不存在'
          break
        case 500:
          message = '服务器错误'
          break
        default:
          message = error.response.data.message || '请求失败'
      }
    }

    // 在登录/注册页面且是401错误时不显示提示
    if (!(isAuthPage && error.response?.status === 401)) {
      ElMessage({
        message: message,
        type: 'error',
        duration: 3000
      })
    }

    return Promise.reject(error)
  }
)

export default service
